def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data")
    if not isinstance(data, list) or len(data) == 0:
        raise Blocked("no community available")
    return statusCode == 200 and responseBody.get("code") == 0 and all(item.get("id") and item.get("name") for item in data) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if responseBody is None:
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(data.get("accessToken")) and bool(data.get("refreshToken")) and bool(responseBody.get("requestId"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(responseBody.get("requestId")) and isinstance(data, dict) and bool(data.get("id"))

def assert_response(responseBody, globalParam, statusCode, headers):
    if not isinstance(responseBody, dict):
        return False
    data = responseBody.get("data") or {}
    return statusCode == 200 and responseBody.get("code") == 0 and bool(responseBody.get("requestId")) and data.get("nickname") == globalParam.get("p_nickname") and data.get("gender") == globalParam.get("p_gender") and data.get("birthDate") == globalParam.get("p_birth")
